[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath)

$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'ProjectPath must be an explicit absolute path.'};$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
Import-Module (Join-Path $ProjectPath 'Research\Gate12RProcessReusePreparation.psm1') -Force
$sourcePath=Join-Path $ProjectPath 'Research\Gate12R_5pct_ProcessReuse_Pilot_Provenance.v5.json';$outputPath=Join-Path $ProjectPath 'Research\Gate12R_5pct_ProcessReuse_Pilot_Provenance.v6.json';$expectedSourceSha256='df5b1990112d8da2f92e1bcb49933967f5abce1c8bea7dba971c2b74fa740de9'
if(Test-Path -LiteralPath $outputPath){throw "Create-new provenance v6 exists: $outputPath"};if((Get-Gate12RLowerSha256 $sourcePath)-ne$expectedSourceSha256){throw 'Frozen provenance v5 hash changed.'}
$v5=Read-Gate12RJson $sourcePath;$bound=New-Object Collections.Generic.List[object];foreach($binding in @($v5.boundFiles)){$bound.Add([pscustomobject][ordered]@{id=[string]$binding.id;relativePath=[string]$binding.relativePath;rawBytes=[long]$binding.rawBytes;sha256=[string]$binding.sha256})}
function Add-Binding([string]$Id,[string]$RelativePath){if(@($bound|Where-Object id -eq $Id).Count-ne0){throw "Duplicate binding id: $Id"};$path=Join-Path $ProjectPath $RelativePath.Replace('/','\');if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw "Binding missing: $RelativePath"};$item=Get-Item -LiteralPath $path;$bound.Add([pscustomobject][ordered]@{id=$Id;relativePath=$RelativePath;rawBytes=[long]$item.Length;sha256=Get-Gate12RLowerSha256 $path})}
Add-Binding 'provenanceV5' 'Research/Gate12R_5pct_ProcessReuse_Pilot_Provenance.v5.json'
Add-Binding 'focusedDiagnosticRunnerV1' 'Research/Verification/Run-Gate12RPlannerResetFocusedDiagnosticV1.ps1'
Add-Binding 'focusedDiagnosticManifestGeneratorV1' 'Research/Verification/New-Gate12RFocusedDiagnosticEvidenceManifest.ps1'
Add-Binding 'focusedDiagnosticSummaryV1' 'Research/Verification/Gate12R_ProcessReuse_5pct/reset-diagnostic-v1/focused-diagnostic-summary.json'
Add-Binding 'focusedDiagnosticEvidenceManifestV1' 'Research/Verification/Gate12R_ProcessReuse_5pct/reset-diagnostic-v1/evidence-manifest.json'
Add-Binding 'focusedDiagnosticCompileSummaryV1' 'Research/Verification/Gate12R_ProcessReuse_5pct/reset-diagnostic-v1/Compile/summary.json'
$manifest=Read-Gate12RJson (Join-Path $ProjectPath 'Research\Verification\Gate12R_ProcessReuse_5pct\reset-diagnostic-v1\evidence-manifest.json');$summary=Read-Gate12RJson (Join-Path $ProjectPath 'Research\Verification\Gate12R_ProcessReuse_5pct\reset-diagnostic-v1\focused-diagnostic-summary.json')
if($manifest.passed-ne$true-or$summary.passed-ne$true-or[int]$summary.freshProcessRepeatCount-ne3-or[int]$summary.distinctProcessIdCount-ne3-or[long]$summary.maximumBlockRetainedManagedGrowthBytes-gt134217728L-or[int]$summary.structuralComparisonCount-ne10){throw 'Focused diagnostic did not pass its frozen gate.'}
foreach($file in @($manifest.files)){$path=Join-Path $ProjectPath ([string]$file.relativePath).Replace('/','\');if(-not(Test-Path $path)-or[long](Get-Item $path).Length-ne[long]$file.rawBytes-or(Get-Gate12RLowerSha256 $path)-ne[string]$file.sha256){throw "Focused diagnostic evidence changed: $($file.relativePath)"}}
if(Test-Path -LiteralPath (Join-Path $ProjectPath 'Research\Verification\Gate12R_ProcessReuse_5pct\v4')){throw 'Official pre-pilot attempt-4 root must remain absent before provenance v6 freeze.'};if(Test-Path -LiteralPath (Join-Path $ProjectPath 'Research\PilotRuns\Gate12R_ProcessReuse_5pct\v2')){throw 'Pilot v2 root must remain absent.'};if(Test-Path -LiteralPath (Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_ProcessReuse_5pct\v1')){throw 'Gate13R formal root must remain absent.'}
$document=[ordered]@{schemaVersion=6;provenanceId='gate12r-fresh-process-reuse-5pct-pilot-provenance-v6-focused-reset-diagnostic-passed';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FROZEN-AFTER-FOCUSED-DIAGNOSTIC-BEFORE-OFFICIAL-PREPILOT-ATTEMPT-4';attempt=4;pilotAttempt=2;implementationRevision=6;changeClass=[string]$v5.changeClass;researchSemanticsChanged=$false;timedWorkloadSemanticsChanged=$false;rawTelemetrySemanticsChanged=$false;cleanupImplementationChanged=$true;frozenThresholdsChanged=$false;executionDesignId=[string]$v5.executionDesignId;config=$v5.config;specification=$v5.specification;testDesign=$v5.testDesign;executionAuthorization=$v5.executionAuthorization;unityCommand=$v5.unityCommand;activePreservationBaseline=$v5.activePreservationBaseline;activeBlockRunner=$v5.activeBlockRunner;activeStaticUnitGate=$v5.activeStaticUnitGate;activeCompileGate=$v5.activeCompileGate;activeTelemetryRunner=$v5.activeTelemetryRunner;activeColdRunner=$v5.activeColdRunner;activeValidationOnlyGate=$v5.activeValidationOnlyGate;activeBlockRegressionGate=$v5.activeBlockRegressionGate;activePilotRunner=$v5.activePilotRunner;activePrePilotAttempt=$v5.activePrePilotAttempt;officialAttempt1=$v5.officialAttempt1;officialAttempt2=$v5.officialAttempt2;officialAttempt3=$v5.officialAttempt3;nonFormalPilotAttempt1=$v5.nonFormalPilotAttempt1;resetContractRepair=$v5.resetContractRepair;focusedResetDiagnostic=[ordered]@{root='Research/Verification/Gate12R_ProcessReuse_5pct/reset-diagnostic-v1';evidenceManifestSha256=Get-Gate12RLowerSha256 (Join-Path $ProjectPath 'Research\Verification\Gate12R_ProcessReuse_5pct\reset-diagnostic-v1\evidence-manifest.json');freshProcessRepeatCount=3;distinctProcessIdCount=3;blockRetainedManagedGrowthBytes=@($summary.blockRetainedManagedGrowthBytes);maximumBlockRetainedManagedGrowthBytes=[long]$summary.maximumBlockRetainedManagedGrowthBytes;frozenManagedLimitBytes=134217728L;structuralComparisonCount=10;passed=$true};boundFiles=$bound.ToArray();authorizedGate11BundleSha256=[string]$v5.authorizedGate11BundleSha256;precisionTargetRelativeHalfWidth=0.05;hardCap=$null;processUnit=[string]$v5.processUnit;formalCampaign=$false;pilotExcludedFromFormalAnalysis=$true;versionedRepairRetryAuthorized=$true;sameAttemptResumeAuthorized=$false;partialAttemptMergeAuthorized=$false;gate13rAuthorized=$false}
Write-Gate12RUtf8NoBomJson -Path $outputPath -Value $document -Depth 50
Write-Host "Gate12R provenance v6 frozen: $outputPath" -ForegroundColor Green

